def transform(grid):
    h,w=len(grid),len(grid[0])
    from collections import Counter
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    fg=next(v for row in grid for v in row if v!=bg)
    out=[row[:] for row in grid]
    for r in range(h):
        p=[c for c in range(w) if grid[r][c]==fg]
        for a,b in zip(p,p[1:]):
            for c in range(a+1,b):
                if grid[r][c]==bg: out[r][c]=2
    for c in range(w):
        p=[r for r in range(h) if grid[r][c]==fg]
        for a,b in zip(p,p[1:]):
            for r in range(a+1,b):
                if grid[r][c]==bg: out[r][c]=2
    return out
